        let (x, _) = resolve_introduction_placement(semio_framework_core::IntroductionPlacement::Right, Some(anchor), (100.0, 50.0), (800.0, 600.0));
        assert!(x <= 800.0 - 100.0 - INTRODUCTION_INFO_BOX_GAP + 0.001);
